import type { StoicClassicalVirtue, StoicRehabExercise, StoicRehabSlot, StoicRehabSuggestedWhen } from "@/types/stoic-rehab";

export const STOIC_REHAB_WEEK_THEMES: Record<number, string> = {
  "1": "Control and calm effort",
  "2": "Four virtues in rehab",
  "3": "Opportunity in challenge",
  "4": "Journal as transformation",
  "5": "Hardship and inner peace",
  "6": "Plato's view — perspective",
  "7": "Resilience under uncertainty",
  "8": "Social courage and normal life",
  "9": "Discipline without harshness",
  "10": "Body trust and calm action",
  "11": "Integration with movement",
  "12": "Ownership and path forward"
};

export const STOIC_REHAB_PROGRAM_DAYS = 84;

export const STOIC_REHAB_SLOT_CHECKLIST_TITLES: Record<StoicRehabSlot, string> = {
  "morning": "Morning Stoic Intention",
  "midday": "Midday Stoic Practice",
  "evening": "Evening Stoic Reflection"
};

function buildExercise(
  day: number,
  slot: StoicRehabSlot,
  contentTitle: string,
  dayTheme: string,
  virtue: StoicClassicalVirtue,
  theory: string,
  task: string,
  journalPrompt: string,
  durationMinutes: number,
  tags: string[],
  intensity: StoicRehabExercise["intensity"],
  suggestedWhen: StoicRehabSuggestedWhen,
): StoicRehabExercise {
  const week = Math.ceil(day / 7);
  const checklistTitle = STOIC_REHAB_SLOT_CHECKLIST_TITLES[slot];
  return {
    id: `stoic-day-${String(day).padStart(2, "0")}-${slot}`,
    day,
    week,
    slot,
    title: `${checklistTitle} · ${contentTitle}`,
    contentTitle,
    dayTheme,
    theme: STOIC_REHAB_WEEK_THEMES[week],
    virtue,
    category: "stoicism",
    theory,
    task,
    journalPrompt,
    durationMinutes,
    tags,
    intensity,
    suggestedWhen,
  };
}

function buildDailyTriad(
  day: number,
  def: {
    dayTheme: string;
    virtue: StoicClassicalVirtue;
    morning: { contentTitle: string; theory: string; task: string; durationMinutes: number; journalPrompt?: string };
    midday: { contentTitle: string; theory: string; task: string; durationMinutes: number; journalPrompt?: string };
    evening: { contentTitle: string; theory: string; task: string; durationMinutes: number; journalPrompt?: string };
    tags: string[];
    intensity: StoicRehabExercise["intensity"];
  },
): StoicRehabExercise[] {
  const { dayTheme, virtue, morning, midday, evening, tags, intensity } = def;
  return [
    buildExercise(day, "morning", morning.contentTitle, dayTheme, virtue, morning.theory, morning.task, morning.journalPrompt ?? "Which one line will guide today?", morning.durationMinutes, tags, "light", "morning"),
    buildExercise(day, "midday", midday.contentTitle, dayTheme, virtue, midday.theory, midday.task, midday.journalPrompt ?? "What happened when you tried this?", midday.durationMinutes, tags, intensity, "during_life"),
    buildExercise(day, "evening", evening.contentTitle, dayTheme, virtue, evening.theory, evening.task, evening.journalPrompt ?? "Did I complete a useful action today?", evening.durationMinutes, tags, "light", "evening"),
  ];
}

